+  <ng-property-tab-header [currentSelectedElement]="currentSelectedElement" />
+  <ng-property-tab-body
+    (inspect)="inspect.emit($event)"
+    (viewSource)="viewSource.emit($event)"
+    [currentSelectedElement]="currentSelectedElement"
