+    expect(content).toContain(`HttpTransferCacheOptions`);
+    expect(content).toContain(`provideConfig({ someConfig: 'foobar' })`);
+    expect(content).not.toContain(
+        `provideHttpClient(withInterceptorsFromDi(), withJsonpSupport())`,
+    );
