@@ -0,0 +1,154 @@
+/**
+ * @license
+ * Copyright Google LLC All Rights Reserved.
+ *
+ * Use of this source code is governed by an MIT-style license that can be
+ * found in the LICENSE file at https://angular.dev/license
+ */
+
+import {fakeAsync, flushMicrotasks, TestBed} from '@angular/core/testing';
+import {
+  HistoryItem,
+  MAX_RECENT_HISTORY_SIZE,
+  SEARCH_HISTORY_LS_KEY,
+  SearchHistory,
+} from './search-history.service';
+import {LOCAL_STORAGE} from '../providers';
+import {MockLocalStorage} from '../testing';
+
+const ITEMS: HistoryItem[] = [
+  {
+    id: 'c',
+    labelHtml: 'Item C',
+  },
+  {
+    id: 'b',
+    labelHtml: 'Item B',
+  },
+  {
+    id: 'a',
+    labelHtml: 'Item A',
+  },
+].map((i) => ({...i, url: '', createdAt: 0, isFavorite: false}));
+
+describe('SearchHistory', () => {
+  let service: SearchHistory;
+  let storage: Storage;
+
+  function loadItems() {
+    for (const item of ITEMS) {
+      // Since adding an item sets a timestamp which is later
+      // used for sorting the items array, we artificially
+      // tick forward the clock and then flush the microtask queue
+      // to ensure proper/expected order. This is needed since we
+      // are updating the internal signal multiple times consecutively.
+      jasmine.clock().tick(100);
+      service.addItem(item);
+      flushMicrotasks();
+    }
+  }
+
+  beforeEach(() => {
+    jasmine.clock().uninstall();
+    jasmine.clock().install();
+
+    TestBed.configureTestingModule({
+      providers: [
+        SearchHistory,
+        {
+          provide: LOCAL_STORAGE,
+          useClass: MockLocalStorage,
+        },
+      ],
+    });
+    service = TestBed.inject(SearchHistory);
+    storage = TestBed.inject(LOCAL_STORAGE)!;
+  });
+
+  afterEach(() => {
+    jasmine.clock().uninstall();
+  });
+
+  it('should be created', () => {
+    expect(service).toBeTruthy();
+  });
+
+  it('should add a history item (both storage and instance)', () => {
+    const item: HistoryItem = {
+      id: 'a',
+      labelHtml: 'Item 1',
+      createdAt: 0,
+      isFavorite: false,
+      url: '',
+    };
+
+    service.addItem(item);
+
+    // Instance check
+    expect(service.items().recent.map((i) => i.id)).toEqual(['a']);
+
+    expect(service.hasItems()).toBeTruthy();
+
+    // Storage check
+    const dataString = storage.getItem(SEARCH_HISTORY_LS_KEY) as string | null;
+    const data = JSON.parse(dataString ?? '') ?? [];
+
+    expect(data?.length).toEqual(1);
+
+    const itemCopy = {...item} as Partial<HistoryItem>;
+    delete itemCopy.createdAt;
+
+    expect(data.pop()).toEqual(jasmine.objectContaining(itemCopy));
+  });
+
+  it('should load history items', fakeAsync(() => {
+    loadItems();
+
+    expect(service.items().recent.map((i) => i.id)).toEqual(['a', 'b', 'c']);
+  }));
+
+  it('should delete a history item', fakeAsync(() => {
+    loadItems();
+
+    const bItem = ITEMS.find((i) => i.id === 'b')!;
+
+    service.removeItem(bItem);
+
+    expect(service.items().recent.map((i) => i.id)).toEqual(['a', 'c']);
+  }));
+
+  it('should make item favorite', fakeAsync(() => {
+    loadItems();
+
+    const aItem = ITEMS.find((i) => i.id === 'a')!;
+
+    service.makeFavorite(aItem);
+
+    expect(service.items().recent.map((i) => i.id)).toEqual(['b', 'c']);
+    expect(service.items().favorite.map((i) => i.id)).toEqual(['a']);
+  }));
+
+  it('should set a limit to history size', fakeAsync(() => {
+    const extra = 10;
+    const ids = [];
+
+    for (let i = 1; i <= MAX_RECENT_HISTORY_SIZE + extra; i++) {
+      const id = i.toString();
+      ids.push(id);
+
+      jasmine.clock().tick(100);
+      service.addItem({
+        id,
+        labelHtml: id,
+        isFavorite: false,
+        url: '',
+        createdAt: 0,
+      });
+      flushMicrotasks();
+    }
+
+    ids.splice(0, extra);
+
+    expect(service.items().recent.map((i) => i.id)).toEqual(ids.reverse());
+  }));
+});
diff --git a/adev/shared-docs/services/search-history.service.ts b/adev/shared-docs/services/search-history.service.ts
new file mode 100644
index 0000000000..ca8a061326
--- /dev/null
+++ b/adev/shared-docs/services/search-history.service.ts
@@ -0,0 +1,112 @@
+/**
+ * @license
+ * Copyright Google LLC All Rights Reserved.
+ *
+ * Use of this source code is governed by an MIT-style license that can be
+ * found in the LICENSE file at https://angular.dev/license
+ */
+
+import {computed, inject, Injectable, signal} from '@angular/core';
+import {LOCAL_STORAGE} from '../providers';
+import {SearchResultItem} from '../interfaces';
+
+// Add version postfix to the key in case (if ever) the data model changes in the future.
+export const SEARCH_HISTORY_LS_KEY = 'docs-search-history-v1';
+
+export const MAX_RECENT_HISTORY_SIZE = 10;
+
+// Represents V1 history item
+export interface HistoryItem {
+  id: string;
+  labelHtml: string;
+  url: string;
+  isFavorite: boolean;
+  createdAt: number;
+}
+
+@Injectable({providedIn: 'root'})
+export class SearchHistory {
+  private readonly localStorage = inject(LOCAL_STORAGE);
+  private readonly history = signal<Map<string, HistoryItem>>(new Map());
+
+  private allItems = computed(() =>
+    Array.from(this.history().values()).sort((a, b) => b.createdAt - a.createdAt),
+  );
+
+  items = computed<{recent: HistoryItem[]; favorite: HistoryItem[]}>(() => ({
+    recent: this.allItems().filter((v) => !v.isFavorite),
+    favorite: this.allItems().filter((v) => v.isFavorite),
+  }));
+
+  hasItems = computed(() => this.allItems().length > 0);
+
+  constructor() {
+    this.loadHistory();
+  }
+
+  addItem(item: SearchResultItem | HistoryItem) {
+    this.updateHistory((map) => {
+      const labelHtml = (item.labelHtml || '').replace(/<\/?mark>/g, '');
+
+      map.set(item.id, {
+        id: item.id,
+        labelHtml,
+        url: item.url,
+        isFavorite: false,
+        createdAt: Date.now(),
+      });
+
+      // `items` still hasn't been updated so we should use `>=`.
+      if (this.items().recent.length >= MAX_RECENT_HISTORY_SIZE) {
+        const {id} = this.items().recent.at(-1)!;
+        map.delete(id);
+      }
+    });
+  }
+
+  removeItem(item: SearchResultItem | HistoryItem) {
+    this.updateHistory((map) => {
+      map.delete(item.id);
+    });
+  }
+
+  makeFavorite(item: SearchResultItem | HistoryItem) {
+    this.updateHistory((map) => {
+      const updated = map.get(item.id);
+      if (updated) {
+        map.set(item.id, {
+          ...updated,
+          isFavorite: true,
+          createdAt: Date.now(),
+        });
+      }
+    });
+  }
+
+  private loadHistory() {
+    let parsedData: HistoryItem[];
+
+    try {
+      const historyData = this.localStorage?.getItem(SEARCH_HISTORY_LS_KEY) as string | null;
+      parsedData = JSON.parse(historyData ?? '[]') as HistoryItem[];
+    } catch {
+      parsedData = [];
+    }
+
+    const history = new Map();
+    for (const item of parsedData) {
+      history.set(item.id, item);
+    }
+    this.history.set(history);
+  }
+
+  private updateHistory(updateFn: (map: Map<string, HistoryItem>) => void) {
+    const history = new Map(this.history());
+    updateFn(history);
+    this.history.set(history);
+
+    try {
+      this.localStorage?.setItem(SEARCH_HISTORY_LS_KEY, JSON.stringify(this.allItems()));
+    } catch {}
+  }
+}
