+async function hydrateFromBlockNameImpl(
+  injector: Injector,
+  blockName: string,
+  onTriggerFn: (deferBlock: any) => void,
+  hydratedBlocks: Set<string>,
+): Promise<{
+  deferBlock: DeferBlock | null;
+  hydratedBlocks: Set<string>;
+}> {
+  const deferBlockRegistry = injector.get(DeferBlockRegistry);
