+      // Inner defer block was not triggered, thus it retains `jsaction` attributes.
+      expect(appHostNode.outerHTML).toContain('<p jsaction="click:;keydown:;" ngb="d1');
+    }, 100_000);
+
+    it('should SSR and hydrate nested `@defer` blocks', async () => {
+      @Component({
+        standalone: true,
+        selector: 'app',
