   }
 }
+
+const parseDate = (inputDate: string | Date): Date => {
+  if (inputDate instanceof Date) {
+    return inputDate;
+  }
+  const outputDate = new Date(inputDate);
+  if (isNaN(outputDate.getTime())) {
+    throw new Error(`Invalid date string: ${inputDate}`);
+  }
+  return outputDate;
+};

