+describe('@let declarations', () => {
+  beforeEach(() => ɵsetEnableLetSyntax(true));
+  afterEach(() => ɵsetEnableLetSyntax(false));
+
+  it('should update the value of a @let declaration over time', () => {
+    @Component({
