+  dispatch(eventInfo: EventInfo, isGlobalDispatch?: boolean): EventInfo | void {
+    const eventInfoWrapper = new EventInfoWrapper(eventInfo);
+    if (eventInfoWrapper.getIsReplay()) {
+      if (isGlobalDispatch || !this.eventReplayer) {
+        return;
+      }
